/* charts.js – Temperaturverlauf + Heizkurve */
'use strict';

var tempChart = null, curveChart = null;

function downsample(arr, maxPts) {
    if (!arr || arr.length <= maxPts) return arr;
    var step = Math.ceil(arr.length / maxPts), out = [];
    for (var i = 0; i < arr.length; i += step) out.push(arr[i]);
    if (out[out.length - 1] !== arr[arr.length - 1]) out.push(arr[arr.length - 1]);
    return out;
}

function renderCharts(hist, thermostat) {
    if (!hist || hist.length < 2) return;
    var c = cc();
    var data = downsample(hist, 500);
    var labels = data.map(function (p) {
        var d = new Date(p.ts);
        return d.getDate().toString().padStart(2, '0') + '. ' + d.getHours().toString().padStart(2, '0') + ':' + d.getMinutes().toString().padStart(2, '0');
    });

    /* Temperaturverlauf */
    var ctx1 = document.getElementById('tempChart').getContext('2d');
    if (tempChart) tempChart.destroy();
    tempChart = new Chart(ctx1, {
        type: 'line', data: {
            labels: labels, datasets: [
                { label: 'Außen', data: data.map(function (p) { return p.outdoor }), borderColor: '#3b82f6', borderWidth: 1.5, pointRadius: 0, tension: .3 },
                { label: 'Vorlauf', data: data.map(function (p) { return p.flow }), borderColor: '#ef4444', borderWidth: 1.5, pointRadius: 0, tension: .3 },
                { label: 'Vorlauf Soll', data: data.map(function (p) { return p.target_flow || p.flow_set }), borderColor: '#ef4444', borderWidth: 1, borderDash: [5, 3], pointRadius: 0, tension: .3 },
                { label: 'Warmwasser', data: data.map(function (p) { return p.dhw }), borderColor: '#f59e0b', borderWidth: 1.5, pointRadius: 0, tension: .3 },
                { label: 'WW Soll', data: data.map(function (p) { return p.dhw_set }), borderColor: '#f59e0b', borderWidth: 1, borderDash: [5, 3], pointRadius: 0, tension: .3 }
            ]
        }, options: {
            responsive: true, maintainAspectRatio: false,
            plugins: { legend: { labels: { color: c.text, font: { size: 11 }, usePointStyle: true, pointStyle: 'line' } } },
            scales: { x: { ticks: { color: c.muted, maxTicksLimit: 14, font: { size: 10 } }, grid: { color: c.grid } }, y: { ticks: { color: c.muted, font: { size: 10 } }, grid: { color: c.grid } } }
        }
    });

    /* Heizkurve */
    _renderCurveChart(data, c, thermostat);

    /* Temperaturverlauf Zusammenfassung */
    _renderTempSummary(data);
}

function _renderCurveChart(data, c, thermostat) {
    var scatter = [], soll = [];
    data.forEach(function (p) {
        if (p.outdoor != null && p.flow != null && p.mode === 'heating') scatter.push({ x: p.outdoor, y: p.flow });
        if (p.outdoor != null && p.target_flow != null) soll.push({ x: p.outdoor, y: p.target_flow });
    });

    /* Berechnete Soll-Heizkurve aus Thermostat-Einstellungen */
    var hc1 = thermostat && thermostat.hc1 ? thermostat.hc1 : {};
    var designTemp = hc1.designtemp || 45;   /* Vorlauf bei minexttemp */
    var minFlow = hc1.minflowtemp || 25;     /* Minimum Vorlauf */
    var maxFlow = hc1.maxflowtemp || 60;     /* Maximum Vorlauf */
    var summerTemp = hc1.summertemp || 18;    /* Ab hier Sommerbetrieb */
    var minExt = (thermostat && thermostat.minexttemp != null) ? thermostat.minexttemp : -10;

    /* Lineare Heizkurve: minExt → designTemp, summerTemp → minFlow */
    var sollCurve = [];
    if (designTemp > minFlow) {
        var step = 1;
        for (var t = minExt; t <= summerTemp + 2; t += step) {
            var vorlauf;
            if (t >= summerTemp) {
                vorlauf = minFlow;
            } else {
                vorlauf = designTemp + (minFlow - designTemp) * (t - minExt) / (summerTemp - minExt);
            }
            vorlauf = Math.max(minFlow, Math.min(maxFlow, vorlauf));
            sollCurve.push({ x: t, y: Math.round(vorlauf * 10) / 10 });
        }
    }

    /* Soll-Kurve: berechnete Heizkurve oder Fallback aus History */
    var sollBins = {};
    soll.forEach(function (p) {
        var bin = Math.round(p.x * 2) / 2;
        if (!sollBins[bin]) sollBins[bin] = { sum: 0, cnt: 0 };
        sollBins[bin].sum += p.y; sollBins[bin].cnt += 1;
    });
    var sollSmooth = Object.keys(sollBins).map(function (k) {
        return { x: parseFloat(k), y: Math.round(sollBins[k].sum / sollBins[k].cnt * 10) / 10 };
    }).sort(function (a, b) { return a.x - b.x });
    /* Berechnete Kurve hat Vorrang, Fallback auf History-Daten */
    /* Soll-Kurve nur im Bereich der Ist-Punkte anzeigen (± 3°C) */
    var sollLine;
    if (sollCurve.length > 0 && scatter.length > 0) {
        var xLo = scatter.reduce(function (a, p) { return Math.min(a, p.x) }, Infinity) - 3;
        var xHi = scatter.reduce(function (a, p) { return Math.max(a, p.x) }, -Infinity) + 3;
        sollLine = sollCurve.filter(function (p) { return p.x >= xLo && p.x <= xHi; });
    } else {
        sollLine = sollCurve.length > 0 ? sollCurve : sollSmooth;
    }

    /* Trendlinie */
    var trendLine = [];
    if (scatter.length >= 3) {
        var n = scatter.length, sx = 0, sy = 0, sxy = 0, sx2 = 0;
        scatter.forEach(function (p) { sx += p.x; sy += p.y; sxy += p.x * p.y; sx2 += p.x * p.x });
        var denom = n * sx2 - sx * sx;
        if (Math.abs(denom) > 0.001) {
            var m = (n * sxy - sx * sy) / denom, b2 = (sy - m * sx) / n;
            var xMin = scatter.reduce(function (a, p) { return Math.min(a, p.x) }, Infinity);
            var xMax = scatter.reduce(function (a, p) { return Math.max(a, p.x) }, -Infinity);
            trendLine = [{ x: xMin, y: Math.round((m * xMin + b2) * 10) / 10 }, { x: xMax, y: Math.round((m * xMax + b2) * 10) / 10 }];
        }
    }

    var alpha = scatter.length < 30 ? .7 : scatter.length < 200 ? .4 : .25;
    var ptSize = scatter.length < 30 ? 4 : scatter.length < 200 ? 3 : 2;
    var allPts = scatter.concat(sollLine);
    var axMinX = allPts.length ? Math.floor(allPts.reduce(function (a, p) { return Math.min(a, p.x) }, Infinity) - 1) : -10;
    var axMaxX = allPts.length ? Math.ceil(allPts.reduce(function (a, p) { return Math.max(a, p.x) }, -Infinity) + 1) : 25;
    var axMinY = allPts.length ? Math.floor(allPts.reduce(function (a, p) { return Math.min(a, p.y) }, Infinity) - 2) : 20;
    var axMaxY = allPts.length ? Math.ceil(allPts.reduce(function (a, p) { return Math.max(a, p.y) }, -Infinity) + 2) : 55;

    var ds = [
        { label: 'Vorlauf (Heizbetrieb)', data: scatter, backgroundColor: 'rgba(239,68,68,' + alpha + ')', pointRadius: ptSize, order: 2 },
        { label: 'Soll (Heizkurve)', data: sollLine, type: 'line', borderColor: '#10b981', borderWidth: 2, pointRadius: 0, tension: .3, fill: false, order: 1 }
    ];
    if (trendLine.length === 2) ds.push({ label: 'Trend (Ist)', data: trendLine, type: 'line', borderColor: 'rgba(251,191,36,0.7)', borderWidth: 2, borderDash: [6, 4], pointRadius: 0, fill: false, order: 0 });

    var ctx2 = document.getElementById('curveChart').getContext('2d');
    if (curveChart) curveChart.destroy();
    curveChart = new Chart(ctx2, {
        type: 'scatter', data: { datasets: ds },
        options: {
            responsive: true, maintainAspectRatio: false,
            plugins: { legend: { labels: { color: c.text, font: { size: 11 } } }, tooltip: { callbacks: { label: function (ctx) { return ctx.dataset.label + ': ' + F(ctx.parsed.x, 1) + '°C → ' + F(ctx.parsed.y, 1) + '°C' } } } },
            scales: {
                x: { min: axMinX, max: axMaxX, title: { display: true, text: 'Außentemperatur °C', color: c.muted }, ticks: { color: c.muted, stepSize: 2 }, grid: { color: c.grid } },
                y: { min: axMinY, max: axMaxY, title: { display: true, text: 'Vorlauftemperatur °C', color: c.muted }, ticks: { color: c.muted }, grid: { color: c.grid } }
            }
        }
    });

    var curveInfo = document.getElementById('curveInfo');
    if (curveInfo) {
        var info = scatter.length + ' Heizpunkte';
        if (scatter.length > 0) { var oMin = scatter.reduce(function (a, p) { return Math.min(a, p.x) }, Infinity); var oMax = scatter.reduce(function (a, p) { return Math.max(a, p.x) }, -Infinity); info += ' · Außen ' + F(oMin, 1) + '–' + F(oMax, 1) + '°C'; }
        if (trendLine.length === 2) info += ' · Trend: ' + F(trendLine[0].y, 1) + '°C → ' + F(trendLine[1].y, 1) + '°C';
        /* Verständliche Zusammenfassung */
        var summary = '';
        if (scatter.length >= 3 && trendLine.length === 2 && sollCurve.length > 0) {
            /* Vergleich: Ist-Trend vs. Soll-Kurve */
            var midX = Math.round((scatter.reduce(function (a, p) { return a + p.x }, 0) / scatter.length) * 10) / 10;
            var sollAtMid = designTemp + (minFlow - designTemp) * (midX - minExt) / (summerTemp - minExt);
            sollAtMid = Math.max(minFlow, Math.min(maxFlow, sollAtMid));
            var m = (trendLine[1].y - trendLine[0].y) / (trendLine[1].x - trendLine[0].x);
            var istAtMid = trendLine[0].y + m * (midX - trendLine[0].x);
            var diff = istAtMid - sollAtMid;
            if (Math.abs(diff) < 1.5) {
                summary = '✅ Die Heizung arbeitet im Sollbereich. Bei ' + F(midX, 0) + '°C Außentemperatur liegt der Vorlauf nahe am Soll (' + F(sollAtMid, 0) + '°C).';
            } else if (diff > 0) {
                summary = '⚠️ Der Vorlauf liegt ~' + F(Math.abs(diff), 0) + '°C über dem Soll. Bei ' + F(midX, 0) + '°C außen: Ist ' + F(istAtMid, 0) + '°C vs. Soll ' + F(sollAtMid, 0) + '°C. Die Heizung arbeitet wärmer als nötig.';
            } else {
                summary = 'ℹ️ Der Vorlauf liegt ~' + F(Math.abs(diff), 0) + '°C unter dem Soll. Bei ' + F(midX, 0) + '°C außen: Ist ' + F(istAtMid, 0) + '°C vs. Soll ' + F(sollAtMid, 0) + '°C.';
            }
        } else if (scatter.length < 3) {
            summary = 'ℹ️ Noch wenige Heizpunkte. Die grüne Linie zeigt die eingestellte Heizkurve: Je kälter draußen, desto wärmer der Vorlauf.';
        }
        if (summary) info += '\n' + summary;
        curveInfo.innerHTML = info.replace('\n', '<br>');
    }
}


function _renderTempSummary(data) {
    var el = document.getElementById('tempInfo');
    if (!el || !data || data.length < 2) return;

    /* Außentemperatur Min/Max/Durchschnitt */
    var outVals = data.filter(function (p) { return p.outdoor != null }).map(function (p) { return p.outdoor });
    var outMin = Math.min.apply(null, outVals);
    var outMax = Math.max.apply(null, outVals);
    var outAvg = outVals.reduce(function (a, b) { return a + b }, 0) / outVals.length;

    /* WW Min/Max */
    var wwVals = data.filter(function (p) { return p.dhw != null && p.dhw > 0 }).map(function (p) { return p.dhw });
    var wwMin = wwVals.length ? Math.min.apply(null, wwVals) : 0;
    var wwMax = wwVals.length ? Math.max.apply(null, wwVals) : 0;

    /* Brenner-Zyklen zählen */
    var cycles = 0, wasBurner = false;
    data.forEach(function (p) {
        if (p.burner && !wasBurner) cycles++;
        wasBurner = p.burner;
    });

    /* Heiz-Anteil */
    var heatPts = data.filter(function (p) { return p.mode === 'heating' }).length;
    var dhwPts = data.filter(function (p) { return p.mode === 'dhw' }).length;
    var totalPts = data.length;
    var heatPct = totalPts > 0 ? Math.round(heatPts / totalPts * 100) : 0;
    var dhwPct = totalPts > 0 ? Math.round(dhwPts / totalPts * 100) : 0;

    var parts = [];
    parts.push('Außen ' + F(outMin, 1) + '–' + F(outMax, 1) + '°C (⌀ ' + F(outAvg, 1) + '°C)');
    if (wwVals.length) parts.push('WW ' + F(wwMin, 1) + '–' + F(wwMax, 1) + '°C');
    parts.push(cycles + ' Brennerzyklen');
    if (heatPct > 0 || dhwPct > 0) parts.push('Heizung ' + heatPct + '% · WW ' + dhwPct + '% der Zeit');

    /* Bewertung */
    var note = '';
    if (wwMin > 0 && wwMin < 45) {
        note = ' · ⚠️ WW-Temperatur fiel unter 45°C (' + F(wwMin, 1) + '°C)';
    } else if (outMax - outMin > 15) {
        note = ' · ℹ️ Große Temperaturschwankung außen (' + F(outMax - outMin, 0) + '°C)';
    } else if (cycles === 0) {
        note = ' · ✅ Kein Brennerbetrieb im Zeitraum';
    }

    el.innerHTML = parts.join(' · ') + note;
}
/* dateselector.js – Dropdown Period Selector (hc_smet Style) */
/* Relative periods are ALWAYS recalculated on page load. */
'use strict';

var DS_PERIODS = {
    'Heute': 'today',
    'Gestern': 'gestern',
    'Diese Woche': 'woche',
    'Letzte 7 Tage': '7tage',
    'Letzte 30 Tage': '30tage',
    'Dieser Monat': 'monat'
};

var DS_STORAGE_KEY = 'haco-period-label';

function _dsCalcRange(key) {
    var now = new Date();
    var f = new Date(), t = new Date();
    f.setHours(0, 0, 0, 0);
    t.setHours(23, 59, 59, 999);

    switch (key) {
        case 'today': break;
        case 'gestern':
            f.setDate(now.getDate() - 1);
            t.setDate(now.getDate() - 1);
            break;
        case 'woche':
            var day = now.getDay();
            f.setDate(now.getDate() - day + (day === 0 ? -6 : 1));
            break;
        case '7tage': f.setDate(now.getDate() - 6); break;
        case '30tage': f.setDate(now.getDate() - 29); break;
        case 'monat': f.setDate(1); break;
    }
    return { from: _dsFmtDate(f), to: _dsFmtDate(t) };
}

function _dsFmtDate(d) {
    return d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0');
}

/**
 * Initialize the dropdown period selector.
 * @param {HTMLElement} container - The element to place the selector in
 * @param {Function} onPeriodChange - Callback: ({period, params}) => void
 * @returns {Function} refresh - Call to re-trigger current period
 */
function initDateSelector(container, onPeriodChange) {
    var savedLabel = localStorage.getItem(DS_STORAGE_KEY) || 'Heute';

    if (DS_PERIODS[savedLabel]) {
        /* OK */
    } else if (!savedLabel.match(/^Jahr /) && savedLabel !== 'Individuell') {
        savedLabel = 'Heute';
    }

    var currentYear = new Date().getFullYear();
    var yearOptions = '';
    for (var y = currentYear; y >= 2026; y--) {
        yearOptions += '<option value="' + y + '">Jahr ' + y + '</option>';
    }

    /* Inject styles */
    if (!document.getElementById('ds-styles')) {
        var style = document.createElement('style');
        style.id = 'ds-styles';
        style.textContent =
            '.ds-wrap { position: relative; display: inline-flex; align-items: center; gap: 6px; }' +
            '.ds-label { font-size: 1.0rem; color: var(--muted); text-transform: uppercase; }' +
            '.ds-btn { padding: 6px 14px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface); color: var(--text); cursor: pointer; font-size: .82rem; font-weight: 500; }' +
            '.ds-btn::after { content: " \\25BE"; opacity: .6; }' +
            '.ds-dropdown { position: absolute; top: calc(100% + 6px); left: 0; min-width: 220px; border-radius: 12px; padding: 6px; z-index: 9999; max-height: 420px; overflow-y: auto; backdrop-filter: blur(30px) saturate(160%); -webkit-backdrop-filter: blur(30px) saturate(160%); box-shadow: 0 16px 48px rgba(0,0,0,.35); background: rgba(13, 20, 38, 0.94); border: 1px solid rgba(255,255,255,.12); }' +
            'body.light .ds-dropdown { background: rgba(255,255,255,.92); border: 1px solid rgba(0,0,0,.08); box-shadow: 0 16px 48px rgba(0,0,0,.15); }' +
            '.ds-dropdown.hidden { display: none; }' +
            '.ds-section { font-size: .68rem; font-weight: 700; color: var(--muted); padding: 8px 12px 2px; text-transform: uppercase; letter-spacing: .5px; }' +
            '.ds-item { padding: 8px 12px; border-radius: 8px; font-size: .82rem; color: var(--text); cursor: pointer; }' +
            '.ds-item:hover { background: rgba(128,128,128,.12); }' +
            '.ds-item.active { background: var(--accent); color: #fff; }' +
            '.ds-select { width: calc(100% - 24px); margin: 4px 12px; padding: 6px; border-radius: 6px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-size: .82rem; }' +
            '.ds-custom { padding: 8px 12px; display: none; }' +
            '.ds-custom.show { display: flex; flex-direction: column; gap: 6px; }' +
            '.ds-custom input { padding: 5px 8px; border-radius: 6px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-size: .82rem; }' +
            '.ds-custom button { padding: 6px; border-radius: 6px; border: none; background: var(--accent); color: #fff; font-size: .82rem; cursor: pointer; font-weight: 600; }';
        document.head.appendChild(style);
    }

    /* Build HTML */
    var wrap = document.createElement('div');
    wrap.className = 'ds-wrap';
    wrap.innerHTML =
        '<span class="ds-label">Zeitraum</span>' +
        '<button class="ds-btn" id="dsBtn">' + savedLabel + '</button>' +
        '<div class="ds-dropdown hidden" id="dsDrop">' +
            '<div class="ds-section">Zeitraum</div>' +
            '<div class="ds-item" data-key="today">Heute</div>' +
            '<div class="ds-item" data-key="gestern">Gestern</div>' +
            '<div class="ds-item" data-key="woche">Diese Woche</div>' +
            '<div class="ds-item" data-key="7tage">Letzte 7 Tage</div>' +
            '<div class="ds-item" data-key="30tage">Letzte 30 Tage</div>' +
            '<div class="ds-item" data-key="monat">Dieser Monat</div>' +
            '<div class="ds-section">Archiv</div>' +
            '<select class="ds-select" id="dsYear">' +
                '<option value="">Jahr ausw\u00E4hlen\u2026</option>' +
                yearOptions +
            '</select>' +
            '<div class="ds-section" style="cursor:pointer" id="dsCustomToggle">Benutzerdefiniert\u2026</div>' +
            '<div class="ds-custom" id="dsCustom">' +
                '<input type="date" id="dsFrom">' +
                '<input type="date" id="dsTo">' +
                '<button id="dsApply">Anwenden</button>' +
            '</div>' +
        '</div>';

    container.appendChild(wrap);

    var btn = wrap.querySelector('#dsBtn');
    var drop = wrap.querySelector('#dsDrop');
    var yearSel = wrap.querySelector('#dsYear');
    var customToggle = wrap.querySelector('#dsCustomToggle');
    var customBox = wrap.querySelector('#dsCustom');
    var fromInput = wrap.querySelector('#dsFrom');
    var toInput = wrap.querySelector('#dsTo');
    var applyBtn = wrap.querySelector('#dsApply');

    /* Toggle dropdown */
    btn.addEventListener('click', function (e) { e.stopPropagation(); drop.classList.toggle('hidden'); });
    document.addEventListener('click', function () { drop.classList.add('hidden'); });
    drop.addEventListener('click', function (e) { e.stopPropagation(); });

    /* Fire period change */
    function fire(label) {
        savedLabel = label;
        localStorage.setItem(DS_STORAGE_KEY, label);
        btn.textContent = label;
        drop.classList.add('hidden');

        /* Highlight active */
        drop.querySelectorAll('.ds-item').forEach(function (el) {
            var itemLabel = el.textContent.trim();
            el.classList.toggle('active', itemLabel === label);
        });

        if (DS_PERIODS[label]) {
            var key = DS_PERIODS[label];
            var range = _dsCalcRange(key);
            if (key === 'today' || key === 'gestern') {
                onPeriodChange({ period: 'today', params: { date: range.from } });
            } else {
                onPeriodChange({ period: 'day', params: { from: range.from, to: range.to } });
            }
        } else if (label.match(/^Jahr /)) {
            var yr = label.replace('Jahr ', '');
            onPeriodChange({ period: 'month', params: { from: yr + '-01-01', to: yr + '-12-31' } });
        } else if (label === 'Individuell') {
            var f = fromInput.value;
            var t = toInput.value;
            if (f && t) {
                onPeriodChange({ period: 'day', params: { from: f, to: t } });
            }
        }
    }

    /* Item clicks */
    drop.querySelectorAll('.ds-item').forEach(function (item) {
        item.addEventListener('click', function () {
            var key = item.dataset.key;
            var labels = { today: 'Heute', gestern: 'Gestern', woche: 'Diese Woche', '7tage': 'Letzte 7 Tage', '30tage': 'Letzte 30 Tage', monat: 'Dieser Monat' };
            fire(labels[key] || key);
        });
    });

    /* Year select */
    yearSel.addEventListener('change', function () {
        if (yearSel.value) fire('Jahr ' + yearSel.value);
    });

    /* Custom toggle */
    customToggle.addEventListener('click', function () { customBox.classList.toggle('show'); });

    /* Custom apply */
    applyBtn.addEventListener('click', function () {
        if (fromInput.value && toInput.value) fire('Individuell');
    });

    /* Initial fire */
    if (savedLabel.match(/^Jahr /)) {
        yearSel.value = savedLabel.replace('Jahr ', '');
    }
    fire(savedLabel);

    /* Return refresh function */
    return function () { fire(savedLabel); };
}
/* daily.js – Energie/Kosten/Laufzeiten Chart + CSV Export */
'use strict';

var dailyChart = null;
var _dailyRefresh = null;

function exportCSV() {
    window.location.href = _bp + '/api/export?days=30';
}

function loadDaily(from, to) {
    var url = _bp + '/api/daily?from=' + from + '&to=' + to;
    _fetch(url).then(function (r) { return r.json(); }).then(function (res) { renderDaily(res.data || []); }).catch(function () { });
}

function renderDaily(data) {
    if (!data || !data.length) return;
    var c = cc();
    _fetch(_bp + '/api/config').then(function (r) { return r.json(); }).then(function (cfg) {
        _renderDailyInner(data, c, cfg.gas_price_kwh || 0.103);
    }).catch(function () { _renderDailyInner(data, c, 0.103); });
}

function _renderDailyInner(data, c, gpk) {
    try {
        var labels = data.map(function (d) {
            if (d.day.indexOf(':') > -1) return d.day;
            var parts = d.day.split('-');
            if (parts.length === 2) return parts[1] + '/' + parts[0];
            return parts[2] + '.' + parts[1];
        });

        var disData = data.map(function (d) {
            if (d.day.indexOf(':') > -1) return 0;
            var dt = new Date(d.day);
            return (!isNaN(dt) && dt.getDay() === 6) ? Math.min(d.dhw_kwh, d.energy_kwh * 0.05) : 0;
        });
        var wwOnly = data.map(function (d, i) { return Math.max(0, d.dhw_kwh - disData[i]); });

        var ctx = document.getElementById('dailyChart').getContext('2d');
        if (dailyChart) dailyChart.destroy();
        dailyChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    { label: '🏠 Heizung', data: data.map(function (d) { return d.heat_kwh; }), backgroundColor: 'rgba(239,68,68,0.7)', stack: 'kwh', yAxisID: 'y' },
                    { label: '💧 Warmwasser', data: wwOnly, backgroundColor: 'rgba(59,130,246,0.7)', stack: 'kwh', yAxisID: 'y' },
                    { label: '🧹 Desinfektion', data: disData, backgroundColor: 'rgba(245,158,11,0.7)', stack: 'kwh', yAxisID: 'y' },
                    { label: '⛽ Gas m³', data: data.map(function (d) { return d.gas_m3 || 0; }), type: 'line', borderColor: '#f59e0b', borderWidth: 2, pointRadius: 2, tension: .3, yAxisID: 'y1', fill: false, borderDash: [4, 2] },
                    { label: '💰 Kosten €', data: data.map(function (d) { return Math.round(d.energy_kwh * gpk * 100) / 100; }), type: 'line', borderColor: '#10b981', borderWidth: 2, pointRadius: 3, tension: .3, yAxisID: 'y1', fill: false }
                ]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                plugins: { legend: { labels: { color: c.text, font: { size: 11 }, usePointStyle: true } } },
                scales: {
                    x: { ticks: { color: c.muted, font: { size: 10 } }, grid: { color: c.grid }, stacked: true },
                    y: { title: { display: true, text: 'kWh', color: c.muted }, ticks: { color: c.muted }, grid: { color: c.grid }, stacked: true, position: 'left' },
                    y1: { title: { display: true, text: 'm³ / €', color: c.muted }, ticks: { color: c.muted }, grid: { display: false }, position: 'right' }
                }
            }
        });

        /* Zusammenfassung */
        var sumE = 0, sumH = 0, sumD = 0, sumG = 0, sumB = 0, sumDis = 0;
        data.forEach(function (d, i) { sumE += d.energy_kwh; sumH += d.heat_kwh; sumD += d.dhw_kwh; sumG += d.gas_m3; sumB += d.burner_min; sumDis += disData[i]; });
        var sumWW = sumD - sumDis, days = data.length;
        var s = '<div style="display:flex;flex-wrap:wrap;gap:12px;justify-content:center;padding:6px 0">';
        s += '<span>Σ <b>' + F(sumE, 1) + '</b> kWh</span>';
        s += '<span style="color:var(--heat)">🏠 ' + F(sumH, 1) + ' kWh</span>';
        s += '<span style="color:var(--dhw)">💧 ' + F(sumWW, 1) + ' kWh</span>';
        if (sumDis > 0) s += '<span style="color:var(--orange)">🧹 ' + F(sumDis, 1) + ' kWh</span>';
        s += '<span>⛽ ' + F(sumG, 2) + ' m³</span>';
        s += '<span style="color:var(--green)">💰 ' + F(sumE * gpk, 2) + ' €</span>';
        s += '<span>⏱ ' + fH(sumB) + '</span>';
        if (days > 1) s += '<span style="color:var(--muted)">⌀ ' + F(sumE / days, 1) + ' kWh/' + (days > 90 ? 'Monat' : 'Tag') + '</span>';
        s += '</div>';
        document.getElementById('mainTable').innerHTML = s;
    } catch (e) {
        document.getElementById('mainTable').textContent = 'Fehler: ' + e.message;
    }
}

